SELECT * FROM squad_workflow_snapshot
WHERE workspace_id = #{workspaceId} AND squad_id = #{squadId}
  AND input_hash = #{inputHash} AND analysis_version = #{analysisVersion}
LIMIT 1

SELECT * FROM squad_workflow_snapshot
WHERE workspace_id = #{workspaceId} AND id = #{id}
LIMIT 1

SELECT * FROM squad_workflow_snapshot
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

SELECT COUNT(*) FROM squad_workflow_snapshot
WHERE workspace_id = #{workspaceId}
  AND status IN


        #{status}

    (NULL)

  AND (deadline_at IS NULL OR deadline_at > #{now})

SELECT * FROM squad_workflow_snapshot
WHERE status IN ('GENERATING', 'REPAIRING')
  AND deadline_at IS NOT NULL AND deadline_at <= #{now}
ORDER BY id ASC
LIMIT #{limit}

SELECT * FROM squad_workflow_snapshot
WHERE status IN ('GENERATING', 'REPAIRING')
  AND conversation_id IS NULL
  AND gmt_modified < #{cutoff}
ORDER BY id ASC
LIMIT #{limit}
